services=[('training','Training','Individuelle Trainingspläne.<br><em>Für deine Ziele.</em>','Vom einzelnen individuellen Trainingsplan bis zur strukturierten Trainingsperiodisierung über zwölf Monate: Dein Training wird auf deinen Trainingsstand, deine Ziele und deinen Alltag abgestimmt.','tatjana-gym','CHF 70.– bis CHF 200.–','Einzelne Trainingspläne bis zur Trainingsperiodisierung über 12 Monate · Preis abhängig vom Umfang','Wir stimmen deine Trainingsstruktur auf Ziele, Trainingsstand, Alltag und Bedürfnisse ab. Du kannst einen einzelnen Trainingsplan oder eine längerfristige Periodisierung über bis zu zwölf Monate wählen. Bei der Periodisierung werden aufeinander aufbauende Trainingsphasen geplant und Belastung und Erholung sinnvoll aufeinander abgestimmt.',['Muskelaufbau und Kraft','Körperkomposition und Leistungssteigerung','Trainingsstruktur passend zu deinem Alltag','Berücksichtigung deiner Erfahrung und Möglichkeiten']),('ernaehrung','Ernährung & Supplemente','Ernährung &amp;<br><em>Supplemente.</em>','Ernährung darf zu deinen Zielen passen und Freude machen. Gemeinsam finden wir praktische Möglichkeiten für deinen Alltag.','tatjana-dining','CHF 150.–','Ernährungs- inkl. Supplementplan · Erstgespräch ca. 1–2 Stunden','Wir betrachten deine aktuelle Ernährung, deine Lebensmittelauswahl und die Umsetzung im Alltag. Supplemente werden nach individuellem Bedarf besprochen. Auf Wunsch können Ansätze aus Ayurveda berücksichtigt werden.',['Persönliche Ernährungsberatung','Analyse deiner aktuellen Ernährung','Lebensmittelauswahl und praktische Umsetzung','Individuelle Planung inklusive Supplementen']),('zyklus','Wohlbefinden & Leistung','Lifestyle-Coaching.<br><em>Für deine Balance.</em>','Persönliche Lifestyle-Beratung für Frauen und Männer, die ihr Wohlbefinden und ihre Leistungsfähigkeit bewusst unterstützen möchten. Ernährung, Schlaf, Regeneration, Trainingsbelastung und Supplemente betrachten wir gemeinsam.','tatjana-lake','CHF 100.– pro Stunde','Zeitaufwand und Kosten werden vorab besprochen.','Ob im Berufsalltag, in der Freizeit oder beim Training: Wir schauen auf deine Ziele, Gewohnheiten und die Balance zwischen Belastung und Erholung. Auch Männer finden hier Unterstützung bei Fragen zu Ernährung, Regeneration, Supplementen und hormonellem Wohlbefinden im Lifestyle-Kontext. Für Frauen bleiben Zyklus und Veränderungen rund um hormonelle Verhütung Teil der Begleitung.',['Wohlbefinden und Leistungsfähigkeit in Alltag, Beruf und Training','Ernährung, Schlaf, Stressbewältigung und Regeneration','Individuelle Auswahl und alltagstaugliche Einnahmeplanung von Supplementen','Berücksichtigung bereits ärztlich beurteilter Laborbefunde, auch zu Hormonwerten','Zyklus und hormonelles Wohlbefinden im Lifestyle-Kontext'])]
for slug,label,title,lead,img,price,meta,txt,items in services:
 extra=''
 if slug=='zyklus':extra='''<section class="soft"><div class="wrap section"><p class="eyebrow">Deine Themen im Mittelpunkt</p><h2>Individuelle Begleitung.<br>Für Frauen und Männer.</h2><div class="steps"><article><h3>Alltag, Beruf & Training</h3><p>Wir betrachten deine Tagesstruktur, Ernährung, Schlafgewohnheiten und Trainingsbelastung. Gemeinsam suchen wir umsetzbare Schritte, die zu deinen Anforderungen und Erholungsbedürfnissen passen.</p></article><article><h3>Supplemente sinnvoll planen</h3><p>Wir besprechen vorhandene Produkte und mögliche Ergänzungen deiner Ernährung. Auswahl und Einnahmeplanung orientieren sich an deiner Ernährung, den Herstellerangaben und gegebenenfalls ärztlichen Empfehlungen. Mögliche Wechselwirkungen mit Medikamenten klärst du ärztlich oder in der Apotheke ab.</p></article><article><h3>Zyklus & Wohlbefinden</h3><p>Für Frauen bietet die Beratung weiterhin Raum für Zyklus, Selbstwahrnehmung und Veränderungen rund um hormonelle Verhütung. Im Mittelpunkt stehen passende Gewohnheiten in Ernährung, Training und Regeneration.</p></article></div></div></section><section class="wrap narrow section"><p class="eyebrow">Vorhandene Laborbefunde</p><h2>Ärztliche Erkenntnisse<br>im Alltag berücksichtigen.</h2><p>Du hast bereits ärztlich beurteilte Blut- oder Hormonwerte? Auf Wunsch berücksichtigen wir die daraus vorliegenden ärztlichen Empfehlungen bei deiner Ernährungs-, Supplement- und Lifestyle-Planung. Das gilt für Frauen und Männer.</p><p>Die medizinische Bedeutung der Werte, mögliche Ursachen und ein allfälliger Behandlungsbedarf werden ärztlich geklärt. Im Coaching geht es darum, passende Schritte für deinen Alltag zu finden.</p></section><section class="wrap section"><p class="eyebrow">Möglicher Ablauf</p><h2>Zeit, um genauer hinzuschauen.</h2><div class="steps"><article><span>01</span><h3>Erstgespräch</h3><p>Ca. 1 Stunde zum Kennenlernen und Besprechen deiner Anliegen.</p></article><article><span>02</span><h3>Vorbereitung</h3><p>Wenn bereits ärztlich beurteilte Laborbefunde vorliegen, können ca. 1–2 weitere Stunden zur Vorbereitung der Lifestyle-Beratung hinzukommen. Der Umfang wird vorab vereinbart.</p></article><article><span>03</span><h3>Besprechung</h3><p>Ca. 1 Stunde für mögliche Schritte in Ernährung, Training und Lifestyle.</p></article></div><p class="notice">Die Beratung umfasst Ernährung, Training und Lifestyle. Sie beinhaltet keine medizinische Auswertung von Hormonwerten, keine Diagnose und keine Behandlung von Hormonstörungen oder anderen Erkrankungen. Laboruntersuchungen und die medizinische Beurteilung der Ergebnisse erfolgen durch entsprechend qualifizierte Fachpersonen. Anhaltende Beschwerden, auffällige Werte und Entscheidungen über Medikamente, Hormonpräparate oder hormonelle Verhütung gehören in ärztliche Betreuung. Es werden keine Heilungs- oder Leistungsversprechen abgegeben.</p></section>'''
 if slug=='ernaehrung':extra='<section class="wrap narrow bottom"><p class="notice">Vorhandene Laborwerte können im zulässigen Coaching-Rahmen berücksichtigt werden. Medizinische Befunde und auffällige Werte gehören in ärztliche Abklärung.</p></section>'
 page(slug,label,head('Coaching / '+label,title,lead)+'<section class="wrap split bottom"><div>'+service_photo(img,label)+'</div><div><h2>Individuell auf dich abgestimmt.</h2><p>'+txt+'</p><ul class="checks">'+''.join('<li>'+x+'</li>' for x in items)+'</ul><div class="price-box"><strong>'+price+'</strong><p>'+meta+'</p><p>Vor Ort oder online'+(' via Zoom' if slug=='ernaehrung' else '')+'.</p>'+link('kontakt','Beratung anfragen ↗')+'</div></div></section>'+extra+cta())
page('ueber-tatjana','Über Tatjana',head('Über Tatjana','Tatjana Geiter.<br><em>Erfahrung &amp; Herz.</em>','Ich bin Tatjana. Kraftsport, Ernährung und die Frage, was uns im Alltag wirklich guttut, begleiten mich seit vielen Jahren.')+'''<section class="wrap split bottom"><div>'''+pic('tatjana-winter','Tatjana in einer sonnigen Winterlandschaft','rounded')+'''<p class="small">Bewegung und Erholung gehören für mich zusammen.</p></div><div><h2>Mein Weg zur Balance.</h2><p>Seit über 15 Jahren trainiere ich im Kraftsport. 2021 stand ich bei einem Bodybuilding-Wettkampf in der Figur-Klasse auf der Bühne. Diese Erfahrung ist ein Teil meiner Geschichte – genauso wie meine langjährige Beschäftigung mit Ernährung und verschiedenen Ernährungskonzepten.</p><p>Auch eigene Erfahrungen mit zyklusbedingten Beschwerden und hormonellem Wohlbefinden haben meinen Blick erweitert. Heute möchte ich Menschen dabei unterstützen, ihre Ziele zu verfolgen und ihre Lebensqualität zu verbessern.</p><p>Seit ungefähr 2015 bin ich nebenberuflich selbstständig. Der persönliche Kontakt und eine gründliche, empathische Begleitung stehen für mich im Mittelpunkt.</p></div></section><section class="soft"><div class="wrap section split"><div><p class="eyebrow">Was ich mitbringe</p><h2>Eine transparente<br>Grundlage für Vertrauen.</h2></div><div class="qualifications"><article><h3>Eidgenössischer Fachausweis Fitnessinstruktor</h3><p>Fachliche Grundlage meiner Arbeit im Fitnessbereich.</p></article><article><h3>Ernährung, Ayurveda & Supplemente</h3><p>Langjährige persönliche Auseinandersetzung und Selbststudium. Keine medizinische oder therapeutische Ausbildung.</p></article><article><h3>Laborwerte im Coaching-Kontext</h3><p>Selbststudium zur Einordnung im Zusammenhang mit Ernährung, Training und Lifestyle. Medizinische Interpretation und Diagnostik bleiben ärztliche Aufgaben.</p></article></div></div></section><section class="wrap section"><p class="eyebrow">Meine Haltung</p><h2>Du sollst dich gesehen fühlen.</h2><div class="steps"><article><h3>Persönlich & empathisch</h3><p>Deine Erfahrungen und Bedürfnisse sind der Ausgangspunkt.</p></article><article><h3>Gründlich & vernetzt</h3><p>Wir betrachten mögliche Zusammenhänge zwischen Bewegung, Ernährung, Erholung und Alltag.</p></article><article><h3>Individuell & lösungsorientiert</h3><p>Wir suchen Schritte, die zu deinen Möglichkeiten passen.</p></article></div></section>'''+cta())
page('preise','Preise',head('Preise','Coaching-Preise.<br><em>Klar und transparent.</em>','Wir besprechen vor Beginn, welche Begleitung zu deinem Anliegen passt und mit welchem Aufwand du rechnen kannst.')+'''<section class="wrap bottom price-list"><article><div><p class="eyebrow">Ernährung</p><h2>Ernährungs- inkl. Supplementplan</h2><p>Erstgespräch ca. 1–2 Stunden.<br>Vor Ort oder online via Zoom.</p></div><div><strong>CHF 150.–</strong>'''+link('ernaehrung','Details ansehen','text-link')+'''</div></article><article><div><p class="eyebrow">Training</p><h2>Individueller Trainingsplan</h2><p>Abhängig vom Umfang.<br>Einzelne Trainingspläne bis hin zur Trainingsperiodisierung über 12 Monate. Vor Ort oder online.</p></div><div><strong>CHF 70.– bis 200.–</strong>'''+link('training','Details ansehen','text-link')+'''</div></article><article><div><p class="eyebrow">Lifestyle-Beratung</p><h2>Wohlbefinden & Leistung</h2><p>Lifestyle-Beratung für Frauen und Männer: Alltag, Beruf, Training, Supplemente sowie Zyklus und hormonelles Wohlbefinden.</p><p>Erstgespräch ca. 1 Stunde; bei bereits ärztlich beurteilten Laborbefunden Vorbereitung ca. 1–2 Stunden; anschliessende Besprechung ca. 1 Stunde.</p><p>Falls alle Schritte anfallen: insgesamt ca. 3–4 Stunden, entsprechend CHF 300.– bis 400.–. Der tatsächliche Umfang wird vorab vereinbart.</p></div><div><strong>CHF 100.– / Stunde</strong>'''+link('zyklus','Details ansehen','text-link')+'''</div></article></section><section class="wrap narrow bottom"><h2>Ein anderes Anliegen?</h2><p>Individuelle Lösungen können nach einem Erstgespräch zusammengestellt werden. Frag mich gerne nach den Möglichkeiten.</p><p class="small">Ein Beratungsgespräch wird hier nicht als kostenlos angeboten. Allfällige Kosten klären wir vor der Terminvereinbarung.</p></section>'''+cta())
page('wissen','Wissen & Alltag',head('Wissen & Alltag','Kleine Impulse.<br><em>Für deinen Alltag.</em>','Hier findest du Ideen, die du auch ohne Coaching mitnehmen kannst. Den Anfang macht ein Rezept für einen schokoladigen Genussmoment.')+'''<section class="wrap split bottom"><a href="schoko-muffins.html">'''+pic('muffins','Dattel-Schoko-Muffins mit Nüssen – illustratives Rezeptbild','rounded')+'''</a><div><p class="eyebrow">Rezepte / ca. 8 Stück</p><h2>Dattel-Schoko-Muffins</h2><p>Gemahlene Mandeln, Banane und Datteln bilden die Basis. Dazu eine Glasur aus Kakao, Kokosöl und Ahornsirup.</p>'''+link('schoko-muffins','Rezept entdecken ↗')+'''</div></section><section class="soft"><div class="wrap section"><p class="eyebrow">Ein kleiner Anfang</p><h2>Was würde deinem Alltag guttun?</h2><div class="steps"><article><h3>Training</h3><p>Welche Zeitfenster stehen dir realistisch zur Verfügung? Notiere sie, bevor du deinen Trainingsumfang planst.</p></article><article><h3>Ernährung</h3><p>Welche Mahlzeit gelingt dir bereits gut? Sammle einfache Gerichte, die du gerne isst und unkompliziert zubereiten kannst.</p></article><article><h3>Wohlbefinden</h3><p>Wann fühlst du dich im Alltag wohl? Beobachte deine Bedürfnisse ohne Leistungsdruck und halte hilfreiche Gewohnheiten fest.</p></article></div><p class="small">Weitere Beiträge zu Ernährung, Training, Regeneration, Schlaf, Supplementen und Zyklus & Lifestyle sind geplant.</p></div></section>'''+cta())
steps=['Backofen auf 180 °C Ober-/Unterhitze vorheizen. Muffinblech mit Papierformen auslegen und diese bei Bedarf leicht einfetten.','Datteln mit kochendem Wasser übergiessen und ungefähr 20 Minuten einweichen. Wasser abgiessen und etwa 50 ml Einweichwasser zurückbehalten.','Datteln, Einweichwasser, Banane, Eier, Mandelmilch, Mandeln, Kakaopulver, Backpulver und Salz zu einem gleichmässigen Teig pürieren. Bei einem weniger leistungsstarken Stabmixer zuerst die Datteln separat pürieren.','Teig auf die Muffinformen verteilen und auf mittlerer Schiene etwa 20 Minuten backen. Die Muffins sollen fest, aber nicht hart sein. Anschliessend abkühlen lassen.','Kokosöl leicht erwärmen und mit Kakaopulver und Ahornsirup zu einer geschmeidigen Glasur verrühren. Kurz abkühlen lassen, bis die Konsistenz etwas dicker wird.','Muffins mit Ganache bestreichen und nach Wunsch dekorieren.']
page('schoko-muffins','Dattel-Schoko-Muffins',head('Wissen & Alltag / Rezept von Tatjana Geiter','Dattel-Schoko-Muffins','Dattel-Schoko-Muffins mit Mandeln, Banane, Datteln und Ganache. Für ca. 8 Stück.')+'<section class="wrap recipe-top">'+pic('muffins','Illustration der Dattel-Schoko-Muffins; das tatsächliche Backergebnis kann abweichen','rounded recipe-image')+'<p class="small">Illustratives Rezeptbild · ca. 20 Minuten Einweichzeit + ca. 20 Minuten Backzeit, zusätzlich Zubereiten und Abkühlen.</p></section><section class="wrap recipe section"><aside><h2>Zutaten</h2><ul class="ingredients">'+''.join('<li>'+x+'</li>' for x in ['200 g gemahlene Mandeln','3 Eier','1 reife Banane','150 g entsteinte Datteln','50 ml Mandelmilch oder Milch nach Wahl','45 g Kakaopulver','2 TL Backpulver','1 Prise Salz'])+'<li>Ca. 50 ml Einweichwasser</li></ul><h3>Ganache</h3><ul><li>2 EL Kokosöl</li><li>2 EL Kakaopulver</li><li>2 EL Ahornsirup</li></ul><h3>Dekoration</h3><p>Gepufftes Getreide, gehackte Nüsse, getrocknete Beeren oder Toppings nach Wahl.</p><p class="small">Enthält Mandeln und in der Grundvariante Eier; je nach Milch und Toppings weitere Allergene.</p></aside><div><h2>So geht’s</h2><ol class="recipe-steps">'+''.join(f'<li id="zubereitung-{i}"><p>'+x+'</p></li>' for i,x in enumerate(steps,1))+'</ol><p class="notice">Vegane Variante laut Tatjanas Rezept: Eier ersatzlos weglassen und pflanzliche Milch verwenden. Diese Variante wurde nicht separat erprobt; die Konsistenz kann abweichen.</p><button class="button" onclick="window.print()">Rezept drucken</button></div></section>')
