def photo_figure(name,alt,caption,cls=''):
 return '<figure class="photo-story '+cls+'">'+pic('tatjana-'+name,alt)+'<figcaption>'+caption+'</figcaption></figure>'
def before_cta(slug,block):
 f=P/(slug+'.html');s=f.read_text(encoding='utf-8');anchor='<section class="cta wrap">'
 s=s.replace(anchor,block+anchor,1) if anchor in s else s.replace('</main>',block+'</main>');f.write_text(s, encoding='utf-8')
before_cta('ueber-tatjana','<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">Ein Teil meiner Geschichte</p><h2>Von der Wettkampfbühne<br>in den Alltag.</h2></div><p>Mein Wettkampf in der Figur-Klasse 2021 gehört zu meinem sportlichen Weg. Heute bringe ich diese Erfahrung in eine Begleitung ein, die deine persönlichen Ziele und deinen Alltag berücksichtigt.</p></div><div class="stage-gallery">'+photo_figure('stage-front','Tatjana auf der Bodybuilding-Bühne in der Figur-Klasse','Figur-Klasse · Wettkampf 2021')+photo_figure('stage-pose','Tatjana bei einer Pose auf der Wettkampfbühne','Kraftsport als Teil meines Weges')+'</div></section>')
