before_cta('training', '<section class="soft"><div class="wrap section"><p class="eyebrow">Trainingsplanung in Uezwil &amp; online</p><h2>Ein Trainingsplan,<br>der in dein Leben passt.</h2><div class="steps"><article><h3>Dein Ausgangspunkt</h3><p>Wir besprechen deine Ziele, Trainingserfahrung und die Zeit, die dir im Alltag zur Verfügung steht. Daraus ergibt sich, welcher Umfang für deinen Trainingsplan sinnvoll ist.</p></article><article><h3>Deine Trainingsstruktur</h3><p>Du kannst einen einzelnen Plan oder eine Periodisierung über bis zu zwölf Monate wählen. Bei der Periodisierung bauen Trainingsphasen aufeinander auf; Belastung und Erholung werden gemeinsam geplant.</p></article><article><h3>Dein nächster Schritt</h3><p>Die Planung kostet je nach Umfang CHF 70.– bis 200.–. Die Beratung findet in Uezwil im Aargau oder online statt. Umfang und Kosten klären wir vor Beginn.</p></article></div><p>Weitere Informationen findest du bei den <a href="preise.html">Coaching-Preisen</a>. Wenn du auch deine Ernährung betrachten möchtest, entdecke die <a href="ernaehrung.html">Ernährungsberatung mit Supplementplan</a>.</p></div></section>')
before_cta('ernaehrung', '<section class="soft"><div class="wrap section"><p class="eyebrow">Ernährungsberatung in Uezwil &amp; online</p><h2>Deine Ernährung.<br>Deine Möglichkeiten im Alltag.</h2><div class="steps"><article><h3>Persönliches Erstgespräch</h3><p>Wir nehmen uns ca. ein bis zwei Stunden Zeit für deine aktuelle Ernährung, deine Ziele und die praktische Umsetzung. Das Gespräch kann in Uezwil im Aargau oder online via Zoom stattfinden.</p></article><article><h3>Ernährung und Supplemente</h3><p>Der Ernährungs- inkl. Supplementplan kostet CHF 150.–. Deine Lebensmittelauswahl und Gewohnheiten bilden die Grundlage; mögliche Ergänzungen besprechen wir nach individuellem Bedarf.</p></article><article><h3>Zusammenhänge verstehen</h3><p>Ernährung, Training und Erholung beeinflussen deinen Alltag gemeinsam. Wenn du zusätzlich eine Trainingsplanung möchtest, findest du die Möglichkeiten unter <a href="training.html">individuelle Trainingspläne</a>.</p></article></div><p>Lerne <a href="ueber-tatjana.html">Tatjana und ihren Coaching-Ansatz</a> kennen oder frage über die <a href="kontakt.html">Kontaktseite</a> eine Beratung an.</p></div></section>')
before_cta('schoko-muffins', '<section class="wrap narrow bottom recipe-author"><p class="eyebrow">Rezept von Tatjana Geiter</p><h2>Genuss gehört dazu.</h2><p>Ich teile hier ein Rezept für deinen Alltag. Mehr über meinen Hintergrund erfährst du unter <a href="ueber-tatjana.html">Über Tatjana</a>. Wenn du dir eine persönliche Planung wünschst, findest du mein Angebot bei der <a href="ernaehrung.html">Ernährungsberatung in Uezwil und online</a>.</p></section>')

